{
  "units": [
    {
      "quote_ref": "F000:F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section title and number identifying 14 CFR § 91.107 regarding the use of safety belts, shoulder harnesses, and child restraint systems, containing no independent substantive requirement."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F002"],
      "kind": "prohibition",
      "meaning": "Unless otherwise authorized by the Administrator, no pilot may take off a U.S.-registered civil aircraft (excluding a free balloon incorporating a basket or gondola, or an airship type certificated before November 2, 1987) unless the pilot in command ensures that each person on board is briefed on how to fasten and unfasten their safety belt and, if installed, shoulder harness."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F002"],
      "kind": "prohibition",
      "meaning": "Unless otherwise authorized by the Administrator, no pilot may cause a U.S.-registered civil aircraft (excluding a free balloon incorporating a basket or gondola, or an airship type certificated before November 2, 1987) to be moved on the surface, take off, or land unless the pilot in command ensures that each person on board has been notified to fasten his or her safety belt and, if installed, shoulder harness."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F002"],
      "kind": "requirement",
      "meaning": "Unless otherwise authorized by the Administrator and except as otherwise provided in 14 CFR § 91.107(a)(3), each person on board a U.S.-registered civil aircraft (except a free balloon incorporating a basket or gondola, or an airship type certificated before November 2, 1987) must occupy an approved seat or berth with a safety belt and, if installed, shoulder harness, properly secured about him or her during movement on the surface, takeoff, and landing."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F002"],
      "kind": "exception",
      "meaning": "For seaplane and float-equipped rotorcraft operations during movement on the surface, the person pushing off the seaplane or rotorcraft from the dock and the person mooring it at the dock are excepted from the seating and safety belt requirements of 14 CFR § 91.107(a)(3)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F002", "F005"],
      "kind": "permission",
      "meaning": "Notwithstanding the general seating and safety belt requirements of 14 CFR § 91.107(a)(3), a person who has not reached his or her second birthday may be held by an adult occupying an approved seat or berth (except as outlined in § 91.108(j)), provided that the person being held does not occupy or use any restraining device."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F002", "F005"],
      "kind": "permission",
      "meaning": "Notwithstanding the general seating and safety belt requirements of 14 CFR § 91.107(a)(3), a person may use the floor of the aircraft as a seat, provided that the person is on board for the purpose of engaging in sport parachuting."
    },
    {
      "quote_ref": "F008:F009",
      "scope_refs": ["F002", "F005"],
      "kind": "permission",
      "meaning": "Notwithstanding any other requirement of 14 CFR chapter I, a person may occupy an approved child restraint system furnished by the operator or a parent, guardian, or designated attendant, provided that the child is accompanied by a parent, guardian, or attendant designated by the parent or guardian to attend to the safety of the child during the flight."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F002", "F005", "F008", "F010"],
      "kind": "requirement",
      "meaning": "To qualify as an approved child restraint system under 14 CFR § 91.107(a)(3)(iii), a seat manufactured to U.S. standards between January 1, 1981, and February 25, 1985, must bear the label: “This child restraint system conforms to all applicable Federal motor vehicle safety standards” (unless excluded under paragraph (a)(3)(iii)(B)(4))."
    },
    {
      "quote_ref": "F012:F014",
      "scope_refs": ["F002", "F005", "F008", "F010"],
      "kind": "requirement",
      "meaning": "To qualify as an approved child restraint system under 14 CFR § 91.107(a)(3)(iii), a seat manufactured to U.S. standards on or after February 26, 1985, must bear two labels: (1) “This child restraint system conforms to all applicable Federal motor vehicle safety standards”; and (2) “THIS RESTRAINT IS CERTIFIED FOR USE IN MOTOR VEHICLES AND AIRCRAFT” in red lettering (unless excluded under paragraph (a)(3)(iii)(B)(4))."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F002", "F005", "F008", "F010", "F015"],
      "kind": "alternative",
      "meaning": "For seats that do not qualify under paragraphs (a)(3)(iii)(B)(1) or (2), an approved child restraint system may bear a label or markings showing that the seat was manufactured under the standards of the United Nations."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F002", "F005", "F008", "F010", "F015"],
      "kind": "alternative",
      "meaning": "For seats that do not qualify under paragraphs (a)(3)(iii)(B)(1) or (2), an approved child restraint system may bear a label or markings showing that the seat or child restraint device furnished by the operator was approved by the FAA through Type Certificate or Supplemental Type Certificate."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F002", "F005", "F008", "F010", "F015"],
      "kind": "alternative",
      "meaning": "For seats that do not qualify under paragraphs (a)(3)(iii)(B)(1) or (2), an approved child restraint system may bear a label or markings showing that the seat or child restraint device furnished by the operator or one of the qualifying persons (parent, guardian, or designated attendant) was approved by the FAA in accordance with § 21.8(d) of 14 CFR chapter I or Technical Standard Order C-100b or a later version."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F002", "F005", "F008"],
      "kind": "permission",
      "meaning": "The child restraint device manufactured by AmSafe, Inc. (CARES, Part No. 4082) and approved by the FAA in accordance with 14 CFR § 21.305(d) (2010 ed.) may continue to bear a label or markings showing FAA approval in accordance with § 21.305(d) (2010 ed.) of that chapter."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F002", "F005", "F008"],
      "kind": "prohibition",
      "meaning": "Except as provided in § 91.107(a)(3)(iii)(B)(3)(iii) and (iv), booster-type child restraint systems (as defined in FMVSS No. 213, 49 CFR 571.213), vest- and harness-type child restraint systems, and lap held child restraints are not approved for use in aircraft."
    },
    {
      "quote_ref": "F021",
      "scope_refs": ["F002", "F005", "F008", "F020"],
      "kind": "requirement",
      "meaning": "When an approved child restraint system is occupied under 14 CFR § 91.107(a)(3)(iii), the operator must ensure that the restraint system is properly secured to an approved forward-facing seat or berth."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F002", "F005", "F008", "F020"],
      "kind": "requirement",
      "meaning": "When an approved child restraint system is occupied under 14 CFR § 91.107(a)(3)(iii), the operator must ensure that the child is properly secured in the restraint system and does not exceed the specified weight limit for that restraint system."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F002", "F005", "F008", "F020"],
      "kind": "requirement",
      "meaning": "When an approved child restraint system is occupied under 14 CFR § 91.107(a)(3)(iii), the operator must ensure that the restraint system bears the appropriate label(s)."
    },
    {
      "quote_ref": "F024",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "Unless otherwise stated, 14 CFR § 91.107 does not apply to operations conducted under 14 CFR part 121, 125, or 135."
    },
    {
      "quote_ref": "F024",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "Paragraph (a)(3) of 14 CFR § 91.107 does not apply to persons subject to 14 CFR § 91.105."
    },
    {
      "quote_ref": "F025",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Regulatory history and amendment citations for 14 CFR § 91.107, carrying no substantive rights, prohibitions, or duties."
    }
  ]
}
